//! 🧊️ Admitted native BRep topology, analytic geometry, p-curves and all spline arrays.
use super::{SemioBrepSnapshot,BrepVertex,BrepEdge,BrepLoop,BrepLoopEdge,BrepFace,BrepShell,BrepShellFace,BrepSolid,BrepSolidShell,BrepCoedge,BrepCurve,BrepCurve2,BrepSurface,SemioPoint2,SemioPoint3,STDIO_SEMIOBREP_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioBrepSnapshot,String>{native::decode(payload,STDIO_SEMIOBREP_DOCUMENT_SCHEMA,control,binary,document)}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,String>{reader.read_f64_le().map_err(|e|e.to_string())}
fn point2(reader:&mut store::ByteReader<'_>)->Result<SemioPoint2,String>{Ok(SemioPoint2{x:f64(reader)?,y:f64(reader)?})}
fn point3(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,String>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn boolean(reader:&mut store::ByteReader<'_>)->Result<bool,String>{match reader.read_u8().map_err(|e|e.to_string())?{0=>Ok(false),1=>Ok(true),_=>Err("invalid BRep native boolean".into())}}
fn u32(reader:&mut store::ByteReader<'_>)->Result<u32,String>{u32::try_from(reader.read_varint_u64().map_err(|e|e.to_string())?).map_err(|_|"BRep native integer exceeds unsigned32".into())}
fn numbers_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<f64>,String>{native::binary_list(reader,control,limits,entities,|reader,_,_|f64(reader))}
fn curve_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepCurve,String>{native::entities(entities,1,limits)?;Ok(match reader.read_u8().map_err(|e|e.to_string())?{
0=>BrepCurve::Line{origin:point3(reader)?,direction:point3(reader)?},1=>BrepCurve::Circle{center:point3(reader)?,axis:point3(reader)?,radius:f64(reader)?},2=>BrepCurve::Ellipse{center:point3(reader)?,axis:point3(reader)?,radius_major:f64(reader)?,radius_minor:f64(reader)?},
3=>{let control_points=native::binary_list(reader,control,limits,entities,|reader,_,_|point3(reader))?;let weights=numbers_binary(reader,control,limits,entities)?;let degree=u32(reader)?;let knots=numbers_binary(reader,control,limits,entities)?;BrepCurve::Nurbs{control_points,weights,degree,knots}},_=>return Err("invalid BRep native curve kind".into())})}
fn curve2_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepCurve2,String>{native::entities(entities,1,limits)?;Ok(match reader.read_u8().map_err(|e|e.to_string())?{
0=>BrepCurve2::Line{origin:point2(reader)?,direction:point2(reader)?},1=>BrepCurve2::Circle{center:point2(reader)?,radius:f64(reader)?},2=>BrepCurve2::Ellipse{center:point2(reader)?,x_axis:point2(reader)?,radius_major:f64(reader)?,radius_minor:f64(reader)?},
3=>{let control_points=native::binary_list(reader,control,limits,entities,|reader,_,_|point2(reader))?;let weights=numbers_binary(reader,control,limits,entities)?;let degree=u32(reader)?;let knots=numbers_binary(reader,control,limits,entities)?;BrepCurve2::Nurbs{control_points,weights,degree,knots}},_=>return Err("invalid BRep native p-curve kind".into())})}
fn surface_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepSurface,String>{native::entities(entities,1,limits)?;Ok(match reader.read_u8().map_err(|e|e.to_string())?{
0=>BrepSurface::Plane{origin:point3(reader)?,normal:point3(reader)?},1=>BrepSurface::Cylinder{origin:point3(reader)?,axis:point3(reader)?,radius:f64(reader)?},2=>BrepSurface::Cone{origin:point3(reader)?,axis:point3(reader)?,radius:f64(reader)?,half_angle:f64(reader)?},3=>BrepSurface::Sphere{center:point3(reader)?,radius:f64(reader)?},4=>BrepSurface::Torus{center:point3(reader)?,axis:point3(reader)?,major_radius:f64(reader)?,minor_radius:f64(reader)?},
5=>{let control_points=native::binary_list(reader,control,limits,entities,|reader,_,_|point3(reader))?;let weights=numbers_binary(reader,control,limits,entities)?;let u_count=u32(reader)?;let v_count=u32(reader)?;let degree_u=u32(reader)?;let degree_v=u32(reader)?;let knots_u=numbers_binary(reader,control,limits,entities)?;let knots_v=numbers_binary(reader,control,limits,entities)?;BrepSurface::Nurbs{control_points,weights,u_count,v_count,degree_u,degree_v,knots_u,knots_v}},_=>return Err("invalid BRep native surface kind".into())})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioBrepSnapshot,String>{let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|e.to_string())?!=1{return Err("unsupported BRep native format".into())}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;
let vertices=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|Ok(BrepVertex{id:native::text(reader,control)?,point:point3(reader)?,tol:f64(reader)?}))?;
let edges=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|Ok(BrepEdge{id:native::text(reader,control)?,start_vertex:native::text(reader,control)?,end_vertex:native::text(reader,control)?,curve:curve_binary(reader,control,limits,entities)?,tol:f64(reader)?}))?;
let loops=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let edges=native::binary_list(reader,control,limits,entities,|reader,control,_|Ok(BrepLoopEdge{edge:native::text(reader,control)?,orientation:boolean(reader)?}))?;Ok(BrepLoop{id,edges})})?;
let faces=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let outer_loop=native::text(reader,control)?;let inner_loops=native::binary_list(reader,control,limits,entities,|reader,control,_|native::text(reader,control))?;let surface=surface_binary(reader,control,limits,entities)?;let orientation=boolean(reader)?;let tol=f64(reader)?;Ok(BrepFace{id,outer_loop,inner_loops,surface,orientation,tol})})?;
let shells=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let faces=native::binary_list(reader,control,limits,entities,|reader,control,_|Ok(BrepShellFace{face:native::text(reader,control)?,orientation:boolean(reader)?}))?;Ok(BrepShell{id,faces})})?;
let solids=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let shells=native::binary_list(reader,control,limits,entities,|reader,control,_|Ok(BrepSolidShell{shell:native::text(reader,control)?,is_void:boolean(reader)?}))?;Ok(BrepSolid{id,shells})})?;
let coedges=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let edge=native::text(reader,control)?;let forward=boolean(reader)?;let pcurve=if boolean(reader)?{Some(curve2_binary(reader,control,limits,entities)?)}else{None};let prange=(f64(reader)?,f64(reader)?);let loop_id=native::text(reader,control)?;let next=native::text(reader,control)?;let prev=native::text(reader,control)?;Ok(BrepCoedge{id,edge,forward,pcurve,prange,loop_id,next,prev})})?;
let next_label=reader.read_varint_u64().map_err(|e|e.to_string())?;if reader.remaining()!=0{return Err("BRep native trailing bytes".into())}Ok(SemioBrepSnapshot{schema,vertices,edges,loops,faces,shells,solids,coedges,next_label})}
fn bool_text(value:&str)->Result<bool,String>{match value{"0"=>Ok(false),"1"=>Ok(true),_=>Err("invalid BRep native boolean".into())}}
fn u32_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<u32,String>{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse().map_err(|_|"invalid BRep native unsigned32".to_string())})}
fn point2_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint2,String>{let[x,y]=native::record(value,control)?;Ok(SemioPoint2{x:native::float(x,control)?,y:native::float(y,control)?})}
fn point3_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,String>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
fn numbers_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<f64>,String>{native::text_list(value,control,limits,entities,|value,control,_|native::float(value,control))}
fn curve_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepCurve,String>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or("BRep native curve tag missing")?;Ok(match tag{
"L"=>{let[origin,direction]=native::record(value,control)?;BrepCurve::Line{origin:point3_text(origin,control)?,direction:point3_text(direction,control)?}},
"C"=>{let[center,axis,radius]=native::record(value,control)?;BrepCurve::Circle{center:point3_text(center,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?}},
"E"=>{let[center,axis,radius_major,radius_minor]=native::record(value,control)?;BrepCurve::Ellipse{center:point3_text(center,control)?,axis:point3_text(axis,control)?,radius_major:native::float(radius_major,control)?,radius_minor:native::float(radius_minor,control)?}},
"N"=>{let[control_points,weights,degree,knots]=native::record(value,control)?;let control_points=native::text_list(control_points,control,limits,entities,|value,control,_|point3_text(value,control))?;let weights=numbers_text(weights,control,limits,entities)?;let degree=u32_text(degree,control)?;let knots=numbers_text(knots,control,limits,entities)?;BrepCurve::Nurbs{control_points,weights,degree,knots}},_=>return Err("invalid BRep native curve kind".into())})}
fn curve2_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepCurve2,String>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or("BRep native p-curve tag missing")?;Ok(match tag{
"L"=>{let[origin,direction]=native::record(value,control)?;BrepCurve2::Line{origin:point2_text(origin,control)?,direction:point2_text(direction,control)?}},
"C"=>{let[center,radius]=native::record(value,control)?;BrepCurve2::Circle{center:point2_text(center,control)?,radius:native::float(radius,control)?}},
"E"=>{let[center,x_axis,radius_major,radius_minor]=native::record(value,control)?;BrepCurve2::Ellipse{center:point2_text(center,control)?,x_axis:point2_text(x_axis,control)?,radius_major:native::float(radius_major,control)?,radius_minor:native::float(radius_minor,control)?}},
"N"=>{let[control_points,weights,degree,knots]=native::record(value,control)?;let control_points=native::text_list(control_points,control,limits,entities,|value,control,_|point2_text(value,control))?;let weights=numbers_text(weights,control,limits,entities)?;let degree=u32_text(degree,control)?;let knots=numbers_text(knots,control,limits,entities)?;BrepCurve2::Nurbs{control_points,weights,degree,knots}},_=>return Err("invalid BRep native p-curve kind".into())})}
fn surface_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<BrepSurface,String>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or("BRep native surface tag missing")?;Ok(match tag{
"P"=>{let[origin,normal]=native::record(value,control)?;BrepSurface::Plane{origin:point3_text(origin,control)?,normal:point3_text(normal,control)?}},
"C"=>{let[origin,axis,radius]=native::record(value,control)?;BrepSurface::Cylinder{origin:point3_text(origin,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?}},
"O"=>{let[origin,axis,radius,half_angle]=native::record(value,control)?;BrepSurface::Cone{origin:point3_text(origin,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?,half_angle:native::float(half_angle,control)?}},
"S"=>{let[center,radius]=native::record(value,control)?;BrepSurface::Sphere{center:point3_text(center,control)?,radius:native::float(radius,control)?}},
"T"=>{let[center,axis,major_radius,minor_radius]=native::record(value,control)?;BrepSurface::Torus{center:point3_text(center,control)?,axis:point3_text(axis,control)?,major_radius:native::float(major_radius,control)?,minor_radius:native::float(minor_radius,control)?}},
"N"=>{let[control_points,weights,u_count,v_count,degree_u,degree_v,knots_u,knots_v]=native::record(value,control)?;let control_points=native::text_list(control_points,control,limits,entities,|value,control,_|point3_text(value,control))?;let weights=numbers_text(weights,control,limits,entities)?;let u_count=u32_text(u_count,control)?;let v_count=u32_text(v_count,control)?;let degree_u=u32_text(degree_u,control)?;let degree_v=u32_text(degree_v,control)?;let knots_u=numbers_text(knots_u,control,limits,entities)?;let knots_v=numbers_text(knots_v,control,limits,entities)?;BrepSurface::Nurbs{control_points,weights,u_count,v_count,degree_u,degree_v,knots_u,knots_v}},_=>return Err("invalid BRep native surface kind".into())})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioBrepSnapshot,String>{let fields=native::fields(body,["schema","vertices","edges","loops","faces","shells","solids","coedges","nextLabel"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::hex_text(fields[0].ok_or("BRep native schema missing")?,control)?;
let vertices=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,point,tol]=native::record(value,control)?;Ok(BrepVertex{id:native::hex_text(id,control)?,point:point3_text(point,control)?,tol:native::float(tol,control)?})})?;
let edges=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,start_vertex,end_vertex,curve,tol]=native::record(value,control)?;Ok(BrepEdge{id:native::hex_text(id,control)?,start_vertex:native::hex_text(start_vertex,control)?,end_vertex:native::hex_text(end_vertex,control)?,curve:curve_text(curve,control,limits,entities)?,tol:native::float(tol,control)?})})?;
let loops=native::text_list(fields[3].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,edges]=native::record(value,control)?;let id=native::hex_text(id,control)?;let edges=native::text_list(edges,control,limits,entities,|value,control,_|{let[edge,orientation]=native::record(value,control)?;Ok(BrepLoopEdge{edge:native::hex_text(edge,control)?,orientation:bool_text(orientation)?})})?;Ok(BrepLoop{id,edges})})?;
let faces=native::text_list(fields[4].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,outer_loop,inner_loops,surface,orientation,tol]=native::record(value,control)?;let id=native::hex_text(id,control)?;let outer_loop=native::hex_text(outer_loop,control)?;let inner_loops=native::text_list(inner_loops,control,limits,entities,|value,control,_|{let[id]=native::record(value,control)?;native::hex_text(id,control)})?;let surface=surface_text(surface,control,limits,entities)?;Ok(BrepFace{id,outer_loop,inner_loops,surface,orientation:bool_text(orientation)?,tol:native::float(tol,control)?})})?;
let shells=native::text_list(fields[5].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,faces]=native::record(value,control)?;let id=native::hex_text(id,control)?;let faces=native::text_list(faces,control,limits,entities,|value,control,_|{let[face,orientation]=native::record(value,control)?;Ok(BrepShellFace{face:native::hex_text(face,control)?,orientation:bool_text(orientation)?})})?;Ok(BrepShell{id,faces})})?;
let solids=native::text_list(fields[6].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,shells]=native::record(value,control)?;let id=native::hex_text(id,control)?;let shells=native::text_list(shells,control,limits,entities,|value,control,_|{let[shell,is_void]=native::record(value,control)?;Ok(BrepSolidShell{shell:native::hex_text(shell,control)?,is_void:bool_text(is_void)?})})?;Ok(BrepSolid{id,shells})})?;
let coedges=native::text_list(fields[7].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,edge,forward,pcurve,prange,loop_id,next,prev]=native::record(value,control)?;let id=native::hex_text(id,control)?;let edge=native::hex_text(edge,control)?;let forward=bool_text(forward)?;let pcurve=if pcurve=="-"{None}else{Some(curve2_text(pcurve.strip_prefix('~').ok_or("invalid BRep native optional p-curve")?,control,limits,entities)?)};let[a,b]=native::record(prange,control)?;let prange=(native::float(a,control)?,native::float(b,control)?);Ok(BrepCoedge{id,edge,forward,pcurve,prange,loop_id:native::hex_text(loop_id,control)?,next:native::hex_text(next,control)?,prev:native::hex_text(prev,control)?})})?;
let next_label=fields[8].ok_or("BRep native nextLabel missing")?;let next_label=control.scoped_stage(|control|{control.begin_stage(next_label.len())?;for _ in next_label.bytes(){control.step()?;}next_label.parse::<u64>().map_err(|_|"invalid BRep native unsigned64 label".to_string())})?;Ok(SemioBrepSnapshot{schema,vertices,edges,loops,faces,shells,solids,coedges,next_label})}
